# Check for invalid UTF-8 in argv (surrogates)
def check_argv_valid():
    for arg in sys.argv:
        # Check for surrogates U+DC80..U+DCFF (from surrogateescape)
        has_surrogate = False
        for ch in arg:
            o = ord(ch)
            if 0xDC80 <= o <= 0xDCFF:
                has_surrogate = True
                break
            # Also lone surrogates D800-DFFF? Python's surrogateescape uses DC80-DCFF for bytes 80-FF.
            # Also check for unpaired surrogates D800-DBFF, DC00-DFFF? Those would also be invalid, but unlikely from argv.
            # We'll check any surrogate D800-DFFF.
            if 0xD800 <= o <= 0xDFFF:
                has_surrogate = True
                break
